import{_ as s,c as n,a as e,o as i}from"./app-BKm_FHq2.js";const l={};function p(t,a){return i(),n("div",null,[...a[0]||(a[0]=[e(`<h1 id="linux-环境配置常用命令" tabindex="-1"><a class="header-anchor" href="#linux-环境配置常用命令"><span>Linux 环境配置常用命令</span></a></h1><div style="background:#f8f9fa;padding:12px 16px;border-left:3px solid #4CAF50;margin-bottom:16px;border-radius:0 4px 4px 0;font-size:0.9rem;"><div style="display:flex;align-items:center;gap:30px;flex-wrap:wrap;"><div style="display:flex;align-items:center;gap:8px;"><span style="color:#666;">📅</span><span>2024-12-19</span></div><div style="display:flex;align-items:center;gap:8px;"><span style="color:#666;">✍️</span><span>Jixer</span></div></div></div><h2 id="docker" tabindex="-1"><a class="header-anchor" href="#docker"><span>Docker</span></a></h2><p>卸载系统之前的 Docker</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token function">sudo</span> yum remove <span class="token function">docker</span> <span class="token punctuation">\\</span></span>
<span class="line">				  docker-client <span class="token punctuation">\\</span></span>
<span class="line">                  docker-client-latest <span class="token punctuation">\\</span></span>
<span class="line">                  docker-common <span class="token punctuation">\\</span></span>
<span class="line">                  docker-latest <span class="token punctuation">\\</span></span>
<span class="line">                  docker-latest-logrotate <span class="token punctuation">\\</span></span>
<span class="line">                  docker-logrotate <span class="token punctuation">\\</span></span>
<span class="line">                  docker-engine</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>安装必要的工具</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token function">sudo</span> yum <span class="token function">install</span> <span class="token parameter variable">-y</span> yum-utils device-mapper-persistent-data lvm2</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>设置源仓库（阿里云镜像）</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token function">sudo</span> yum-config-manager --add-repo http://mirrors.aliyun.com/docker-ce/linux/centos/docker-ce.repo</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>安装最新社区版docker</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line">yum <span class="token function">install</span> docker-ce</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>启动Docker</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token function">sudo</span> systemctl start <span class="token function">docker</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>配置镜像加速，此处需要根据不同的服务器厂商来配置，例如腾讯云选择腾讯云的 Docker 镜像源</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token function">sudo</span> <span class="token function">mkdir</span> <span class="token parameter variable">-p</span> /etc/docker</span>
<span class="line"><span class="token function">sudo</span> <span class="token function">tee</span> /etc/docker/daemon.json <span class="token operator">&lt;&lt;-</span><span class="token string">&#39;EOF&#39;</span>
<span class="line">{</span>
<span class="line">  &quot;registry-mirrors&quot;: [&quot;https://chqac97z.mirror.aliyuncs.com&quot;]</span>
<span class="line">}</span>
<span class="line">EOF</span></span>
<span class="line"><span class="token function">sudo</span> systemctl daemon-reload</span>
<span class="line"><span class="token function">sudo</span> systemctl restart <span class="token function">docker</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>查看是否安装成功</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token function">docker</span> <span class="token parameter variable">-v</span></span>
<span class="line"><span class="token function">docker</span> info</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>对于 Windows 版本，常出现的问题已经以及解决方案：https://blog.csdn.net/cplvfx/article/details/138033c2</p><h2 id="mysql" tabindex="-1"><a class="header-anchor" href="#mysql"><span>MySQL</span></a></h2><p>Docker 下载</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token function">docker</span> pull mysql:8.0</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>运行</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token function">docker</span> run <span class="token parameter variable">--name</span> mysql:8.0 <span class="token parameter variable">-d</span> <span class="token parameter variable">-p</span> <span class="token number">3306</span>:3306 <span class="token parameter variable">-v</span> /lijunxi/mysql/log:/var/log/mysql <span class="token parameter variable">-v</span> /lijunxi/mysql/data:/var/lib/mysql <span class="token parameter variable">-e</span> <span class="token assign-left variable">MYSQL_ROOT_PASSWORD</span><span class="token operator">=</span>jixer666mysql <span class="token parameter variable">--restart</span><span class="token operator">=</span>always mysql</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="redis" tabindex="-1"><a class="header-anchor" href="#redis"><span>Redis</span></a></h2><p>Docker 下载</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token function">docker</span> pull redis</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>下载配置文件</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token function">wget</span> http://download.redis.io/redis-stable/redis.conf</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>修改配置</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token builtin class-name">bind</span> <span class="token number">127.0</span>.0.1 <span class="token comment"># 这行要注释掉，解除本地连接限制</span></span>
<span class="line">protected-mode no <span class="token comment"># 默认yes，如果设置为yes，则只允许在本机的回环连接，其他机器无法连接。</span></span>
<span class="line">daemonize no <span class="token comment"># 默认no 为不守护进程模式，docker部署不需要改为yes，docker run -d本身就是后台启动，不然会冲突</span></span>
<span class="line">requirepass <span class="token number">123456</span> <span class="token comment"># 设置密码</span></span>
<span class="line">appendonly <span class="token function">yes</span> <span class="token comment"># 持久化</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>运行</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token function">docker</span> run <span class="token parameter variable">--name</span> redis <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-p</span> <span class="token number">6379</span>:6379 <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-v</span> /lijunxi/redis/redis.conf:/etc/redis/redis.conf <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-v</span> /lijunxi/redis/data:/data <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-d</span> redis redis-server /etc/redis/redis.conf <span class="token parameter variable">--appendonly</span> <span class="token function">yes</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="rabbitmq" tabindex="-1"><a class="header-anchor" href="#rabbitmq"><span>RabbitMQ</span></a></h2><p>Docker 下载</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token function">docker</span> pull rabbitmq</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>运行</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token function">docker</span> run <span class="token parameter variable">-d</span> <span class="token parameter variable">--name</span> rabbitmq <span class="token parameter variable">-p</span> <span class="token number">5672</span>:5672 <span class="token parameter variable">-p</span> <span class="token number">15672</span>:15672 <span class="token parameter variable">-v</span> /lijunxi/rabbitmq/data:/var/lib/rabbitmq <span class="token parameter variable">--hostname</span> myRabbit <span class="token parameter variable">-e</span> <span class="token assign-left variable">RABBITMQ_DEFAULT_VHOST</span><span class="token operator">=</span>my_vhost  <span class="token parameter variable">-e</span> <span class="token assign-left variable">RABBITMQ_DEFAULT_USER</span><span class="token operator">=</span>jixer666rabbitmq <span class="token parameter variable">-e</span> <span class="token assign-left variable">RABBITMQ_DEFAULT_PASS</span><span class="token operator">=</span>jixer666rabbitmq rabbitmq</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>开启 Web 管理页面</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token function">docker</span> <span class="token builtin class-name">exec</span> <span class="token parameter variable">-it</span> rabbitmq rabbitmq-plugins <span class="token builtin class-name">enable</span> rabbitmq_management</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="nginx" tabindex="-1"><a class="header-anchor" href="#nginx"><span>Nginx</span></a></h2><p>相关依赖下载</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line">yum <span class="token function">install</span> <span class="token parameter variable">-y</span> gcc-c++ pcre pcre-devel zlib zlib-devel openssl openssl-devel</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>下载 nginx</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token function">wget</span> http://nginx.org/download/nginx-1.25.1.tar.gz</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>解压</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"> <span class="token function">tar</span> <span class="token parameter variable">-zxvf</span> nginx-1.25.1.tar.gz</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>编译安装 nginx</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token builtin class-name">cd</span> nginx-1.25.1/</span>
<span class="line">./configure</span>
<span class="line"><span class="token function">make</span><span class="token operator">&amp;&amp;</span><span class="token function">make</span> <span class="token function">install</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>启动</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token builtin class-name">cd</span> /usr/local/nginx/sbin</span>
<span class="line">./nginx</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="minio" tabindex="-1"><a class="header-anchor" href="#minio"><span>Minio</span></a></h2><p>Docker 下载</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token function">docker</span> pull minio/minio</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>运行，终端的接口为9001，java 代码调用接口为9092</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token function">docker</span> run <span class="token parameter variable">-d</span> <span class="token parameter variable">-p</span> <span class="token number">9000</span>:9000 <span class="token parameter variable">-p</span> <span class="token number">9090</span>:9090 <span class="token parameter variable">--name</span> minio <span class="token parameter variable">-e</span> <span class="token string">&quot;MINIO_ROOT_USER=jixerminio666&quot;</span> <span class="token parameter variable">-e</span> <span class="token string">&quot;MINIO_ROOT_PASSWORD=jixerminio666&quot;</span> <span class="token parameter variable">-v</span> /usr/bin/lijunxi/minio/data:/data <span class="token parameter variable">-v</span> /usr/bin/lijunxi/minio/config:/root/.minio minio/minio server /data --console-address <span class="token string">&quot;:9000&quot;</span> <span class="token parameter variable">--address</span> <span class="token string">&quot;:9090&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="zookeeper" tabindex="-1"><a class="header-anchor" href="#zookeeper"><span>Zookeeper</span></a></h2><p>Docker 下载</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token function">docker</span> pull zookeeper</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>运行</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token function">docker</span> run <span class="token parameter variable">-d</span> <span class="token parameter variable">--name</span> zookeeper <span class="token parameter variable">--privileged</span><span class="token operator">=</span>true <span class="token parameter variable">-p</span> <span class="token number">2181</span>:2181  <span class="token parameter variable">-v</span> /lijunxi/zookeeper/data</span>
<span class="line">:/data <span class="token parameter variable">-v</span> /lijunxi/zookeeper/conf:/conf <span class="token parameter variable">-v</span> /lijunxi/zookeeper/logs:/datalog zookeeper</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="jenkins" tabindex="-1"><a class="header-anchor" href="#jenkins"><span>Jenkins</span></a></h2><table><thead><tr><th style="text-align:left;"><strong>Jenkins 版本</strong></th><th style="text-align:left;"><strong>最低 JDK 要求</strong></th><th style="text-align:left;"><strong>推荐 JDK 版本</strong></th><th style="text-align:left;"><strong>兼容性说明</strong></th></tr></thead><tbody><tr><td style="text-align:left;">Jenkins 2.428 (LTS)</td><td style="text-align:left;">JDK 11</td><td style="text-align:left;">JDK 17</td><td style="text-align:left;">从 2.357 起不再支持 JDK 8。</td></tr><tr><td style="text-align:left;">Jenkins 2.346 (LTS)</td><td style="text-align:left;">JDK 8</td><td style="text-align:left;">JDK 11</td><td style="text-align:left;">最后一个支持 JDK 8 的 LTS 版本。</td></tr><tr><td style="text-align:left;">Jenkins 2.164+</td><td style="text-align:left;">JDK 8</td><td style="text-align:left;">JDK 11</td><td style="text-align:left;">支持 JDK 8/11，但推荐 JDK 11。</td></tr><tr><td style="text-align:left;">Jenkins 2.361+</td><td style="text-align:left;">JDK 11</td><td style="text-align:left;">JDK 17</td><td style="text-align:left;">停止对 JDK 8 的官方支持。</td></tr><tr><td style="text-align:left;">Jenkins 2.387+</td><td style="text-align:left;">JDK 11</td><td style="text-align:left;">JDK 17</td><td style="text-align:left;">新增对 JDK 17 的正式支持。</td></tr></tbody></table><p>Docker 下载</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token function">docker</span> pull jenkins/jenkins:2.346.1-lts</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>启动</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token function">docker</span> run <span class="token parameter variable">-d</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">--name</span> jenkins <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-p</span> <span class="token number">8080</span>:8080 <span class="token parameter variable">-p</span> <span class="token number">50000</span>:50000 <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-v</span> /usr/bin/lijunxi/jenkins:/var/jenkins_home <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-v</span> <span class="token variable"><span class="token variable">$(</span><span class="token function">which</span> <span class="token function">docker</span><span class="token variable">)</span></span>:/usr/bin/docker <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-v</span> /var/run/docker.sock:/var/run/docker.sock <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-u</span> <span class="token number">0</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">--restart</span><span class="token operator">=</span>on-failure:3 <span class="token punctuation">\\</span></span>
<span class="line">  jenkins/jenkins:2.346.1-lts</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token function">docker</span> run <span class="token parameter variable">-d</span> <span class="token parameter variable">--name</span> jenkins <span class="token parameter variable">-p</span> <span class="token number">8080</span>:8080 <span class="token parameter variable">-p</span> <span class="token number">50000</span>:50000 <span class="token parameter variable">-v</span> D:/environment/jenkins:/var/jenkins_home <span class="token parameter variable">-v</span> D:/docker/resources/bin/docker.exe:/usr/bin/docker <span class="token parameter variable">-v</span> /var/run/docker.sock:/var/run/docker.sock <span class="token parameter variable">-u</span> <span class="token number">0</span> <span class="token parameter variable">--restart</span><span class="token operator">=</span>on-failure:3 jenkins/jenkins:2.479.1</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>管理员账号：jixer666jenkins jixer666jenkins</p><h2 id="gitlab" tabindex="-1"><a class="header-anchor" href="#gitlab"><span>Gitlab</span></a></h2><p>Docker 下载</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token function">docker</span> pull gitlab/gitlab-ce:latest</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>启动</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token function">docker</span> run <span class="token punctuation">\\</span></span>
<span class="line"> <span class="token parameter variable">-itd</span>  <span class="token punctuation">\\</span></span>
<span class="line"> <span class="token parameter variable">-p</span> <span class="token number">9980</span>:80 <span class="token punctuation">\\</span></span>
<span class="line"> <span class="token parameter variable">-p</span> <span class="token number">9922</span>:22 <span class="token punctuation">\\</span></span>
<span class="line"> <span class="token parameter variable">-v</span> /home/gitlab/etc:/etc/gitlab  <span class="token punctuation">\\</span></span>
<span class="line"> <span class="token parameter variable">-v</span> /home/gitlab/log:/var/log/gitlab <span class="token punctuation">\\</span></span>
<span class="line"> <span class="token parameter variable">-v</span> /home/gitlab/opt:/var/opt/gitlab <span class="token punctuation">\\</span></span>
<span class="line"> <span class="token parameter variable">--restart</span> always <span class="token punctuation">\\</span></span>
<span class="line"> <span class="token parameter variable">--privileged</span><span class="token operator">=</span>true <span class="token punctuation">\\</span></span>
<span class="line"> <span class="token parameter variable">--name</span> gitlab <span class="token punctuation">\\</span></span>
<span class="line"> gitlab/gitlab-ce</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>gitlab 默认账号：root</p><p>gitlab 默认密码：/etc/gitlab/initial_root_password，自定义后的密码为：Ljx20021106..</p><h2 id="elasticsearch" tabindex="-1"><a class="header-anchor" href="#elasticsearch"><span>Elasticsearch</span></a></h2><p>创建网络</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token function">docker</span> network create es-net</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>拉取镜像</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token function">docker</span> pull elasticsearch:6.5.4</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>启动</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token function">docker</span> run <span class="token parameter variable">-d</span> <span class="token parameter variable">--restart</span><span class="token operator">=</span>no <span class="token parameter variable">--name</span> es <span class="token parameter variable">--network</span> es-net <span class="token parameter variable">-p</span> <span class="token number">9200</span>:9200 <span class="token parameter variable">-p</span> <span class="token number">9300</span>:9300 <span class="token parameter variable">--privileged</span> <span class="token parameter variable">-v</span> /d/environment/elasticsearch/data:/usr/share/elasticsearch/data <span class="token parameter variable">-v</span> /d/environment/elasticsearch/plugins:/usr/share/elasticsearch/plugins <span class="token parameter variable">-e</span> <span class="token string">&quot;discovery.type=single-node&quot;</span> <span class="token parameter variable">-e</span> <span class="token string">&quot;ES_JAVA_OPTS=-Xms512m -Xmx512m&quot;</span> <span class="token parameter variable">-e</span> <span class="token string">&quot;xpack.security.enabled=false&quot;</span> elasticsearch:6.5.4</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="kibana" tabindex="-1"><a class="header-anchor" href="#kibana"><span>Kibana</span></a></h2><p>拉取镜像</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token function">docker</span> pull kibana:6.5.4</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>启动</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token function">docker</span> run <span class="token parameter variable">-d</span> <span class="token parameter variable">--name</span> kibana <span class="token parameter variable">-e</span> <span class="token assign-left variable">ELASTICSEARCH_HOSTS</span><span class="token operator">=</span>http://es:9200 <span class="token parameter variable">--network</span><span class="token operator">=</span>es-net <span class="token parameter variable">-p</span> <span class="token number">5601</span>:5601 kibana:6.5.4</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="zipkin" tabindex="-1"><a class="header-anchor" href="#zipkin"><span>Zipkin</span></a></h2><p>拉取镜像</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token function">docker</span> pull openzipkin/zipkin</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>启动</p><p>内存存储</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token function">docker</span> run <span class="token parameter variable">-d</span> <span class="token parameter variable">-p</span> <span class="token number">9411</span>:9411 <span class="token parameter variable">--name</span> zipkin openzipkin/zipkin</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>MySQL 存储</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token function">docker</span> run <span class="token parameter variable">-d</span> <span class="token parameter variable">-p</span> <span class="token number">9411</span>:9411 <span class="token parameter variable">-e</span> <span class="token assign-left variable">STORAGE_TYPE</span><span class="token operator">=</span>mysql <span class="token parameter variable">-e</span> <span class="token assign-left variable">MYSQL_HOST</span><span class="token operator">=</span><span class="token number">127.0</span>.0.1:3306 <span class="token parameter variable">-e</span> <span class="token assign-left variable">MYSQL_USER</span><span class="token operator">=</span>root <span class="token parameter variable">-e</span> <span class="token assign-left variable">MYSQL_PASS</span><span class="token operator">=</span><span class="token number">123456</span> <span class="token parameter variable">-e</span> <span class="token assign-left variable">MYSQL_DB</span><span class="token operator">=</span>zipkin <span class="token parameter variable">--name</span> zipkin-mysql openzipkin/zipkin</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>ES 存储</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token function">docker</span> run <span class="token parameter variable">-d</span> <span class="token parameter variable">-p</span> <span class="token number">9411</span>:9411 <span class="token parameter variable">-e</span> <span class="token assign-left variable">STORAGE_TYPE</span><span class="token operator">=</span>elasticsearch  <span class="token parameter variable">-e</span> <span class="token assign-left variable">ES_HOSTS</span><span class="token operator">=</span>http://elasticsearch:9200 <span class="token parameter variable">--name</span> zipkin-es openzipkin/zipkin</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="部署项目" tabindex="-1"><a class="header-anchor" href="#部署项目"><span>部署项目</span></a></h2><h3 id="nginx-配置" tabindex="-1"><a class="header-anchor" href="#nginx-配置"><span>Nginx 配置</span></a></h3><p>伪静态</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line">location / <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>-e <span class="token variable">$request_filename</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    rewrite  ^<span class="token punctuation">(</span>.*<span class="token punctuation">)</span>$ /index.html?s<span class="token operator">=</span>/<span class="token variable">$1</span>  last<span class="token punctuation">;</span></span>
<span class="line">    <span class="token builtin class-name">break</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>反向代理</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"> location /api <span class="token punctuation">{</span></span>
<span class="line">          proxy_http_version <span class="token number">1.1</span><span class="token punctuation">;</span></span>
<span class="line">          proxy_set_header Host <span class="token variable">$host</span><span class="token punctuation">;</span></span>
<span class="line">          proxy_set_header X-Real-IP <span class="token variable">$remote_addr</span><span class="token punctuation">;</span></span>
<span class="line">          proxy_set_header X-Forwarded-For <span class="token variable">$proxy_add_x_forwarded_for</span><span class="token punctuation">;</span></span>
<span class="line">          <span class="token comment"># 把 /api 路径下的请求转发给真正的后端服务器</span></span>
<span class="line">  	  proxy_pass http://xxx.xxx.xxx:9898<span class="token punctuation">;</span></span>
<span class="line">      <span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="文件传输" tabindex="-1"><a class="header-anchor" href="#文件传输"><span>文件传输</span></a></h3><p>文件传输到服务器</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token function">scp</span> <span class="token parameter variable">-r</span> D:<span class="token punctuation">\\</span>Springboot<span class="token punctuation">\\</span>Springboot项目<span class="token punctuation">\\</span>blog<span class="token punctuation">\\</span>blog-server<span class="token punctuation">\\</span>target<span class="token punctuation">\\</span>blog-server-1.0-SNAPSHOT.jar root@xxx.xxx.xxx:/lijunxi/project/blog</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="运行-springboot-项目" tabindex="-1"><a class="header-anchor" href="#运行-springboot-项目"><span>运行 SpringBoot 项目</span></a></h3><p><strong>普通方法</strong></p><p>运行 jar 包并输出日志文件，日志文件会按照10mb大小为一个文件保存</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token function">nohup</span> <span class="token function">java</span> <span class="token parameter variable">-jar</span> blog-server-1.0-SNAPSHOT.jar <span class="token operator">&gt;</span> nohup.log <span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span><span class="token file-descriptor important">&amp;1</span> <span class="token operator">&amp;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>查询 java 项目进程</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token function">ps</span> aux <span class="token operator">|</span> <span class="token function">grep</span> <span class="token string">&quot;java -jar&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>杀死进程</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token function">kill</span> <span class="token parameter variable">-9</span> xxx</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><strong>Docker 部署</strong></p><p>编写 Dockerfile 文件</p><div class="language-docker line-numbers-mode" data-highlighter="prismjs" data-ext="docker"><pre><code><span class="line"><span class="token instruction"><span class="token keyword">FROM</span>  openjdk:8</span></span>
<span class="line"><span class="token instruction"><span class="token keyword">VOLUME</span> /usr/bin/lijunxi/test</span></span>
<span class="line"><span class="token instruction"><span class="token keyword">ADD</span> project-admin.jar project-admin.jar</span></span>
<span class="line"><span class="token instruction"><span class="token keyword">EXPOSE</span> 8080</span></span>
<span class="line"><span class="token instruction"><span class="token keyword">ENTRYPOINT</span> [<span class="token string">&quot;java&quot;</span>,<span class="token string">&quot;-jar&quot;</span>,<span class="token string">&quot;/project-admin.jar&quot;</span>]</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>构建镜像</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token function">docker</span> build <span class="token parameter variable">-t</span> archive-demo <span class="token builtin class-name">.</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>运行</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token function">docker</span> run <span class="token parameter variable">-d</span> <span class="token parameter variable">-p</span> <span class="token number">8080</span>:8080 <span class="token parameter variable">--name</span> archive-demo archive-demo</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div>`,121)])])}const c=s(l,[["render",p]]),d=JSON.parse('{"path":"/linux/Linux%E7%8E%AF%E5%A2%83%E9%85%8D%E7%BD%AE%E5%B8%B8%E7%94%A8%E5%91%BD%E4%BB%A4.html","title":"Linux 环境配置常用命令","lang":"en-US","frontmatter":{},"headers":[{"level":2,"title":"Docker","slug":"docker","link":"#docker","children":[]},{"level":2,"title":"MySQL","slug":"mysql","link":"#mysql","children":[]},{"level":2,"title":"Redis","slug":"redis","link":"#redis","children":[]},{"level":2,"title":"RabbitMQ","slug":"rabbitmq","link":"#rabbitmq","children":[]},{"level":2,"title":"Nginx","slug":"nginx","link":"#nginx","children":[]},{"level":2,"title":"Minio","slug":"minio","link":"#minio","children":[]},{"level":2,"title":"Zookeeper","slug":"zookeeper","link":"#zookeeper","children":[]},{"level":2,"title":"Jenkins","slug":"jenkins","link":"#jenkins","children":[]},{"level":2,"title":"Gitlab","slug":"gitlab","link":"#gitlab","children":[]},{"level":2,"title":"Elasticsearch","slug":"elasticsearch","link":"#elasticsearch","children":[]},{"level":2,"title":"Kibana","slug":"kibana","link":"#kibana","children":[]},{"level":2,"title":"Zipkin","slug":"zipkin","link":"#zipkin","children":[]},{"level":2,"title":"部署项目","slug":"部署项目","link":"#部署项目","children":[{"level":3,"title":"Nginx 配置","slug":"nginx-配置","link":"#nginx-配置","children":[]},{"level":3,"title":"文件传输","slug":"文件传输","link":"#文件传输","children":[]},{"level":3,"title":"运行 SpringBoot 项目","slug":"运行-springboot-项目","link":"#运行-springboot-项目","children":[]}]}],"git":{"updatedTime":1772378218000,"contributors":[{"name":"lijunxi","username":"lijunxi","email":"2770063826@qq.com","commits":9,"url":"https://github.com/lijunxi"}],"changelog":[{"hash":"9f2e2eae9bf1528af2a053782edcdc5a1967682a","time":1772378218000,"email":"2770063826@qq.com","author":"lijunxi","message":"add vuepress"},{"hash":"9f78a66735d62daa513a7fd014d9b4ce4cfba4e1","time":1770814834000,"email":"2770063826@qq.com","author":"lijunxi","message":"add hexo-blog、add im-server-deploy"},{"hash":"88975dd0114a3f592c5bb5025a914b4d47ffc10a","time":1765718893000,"email":"2770063826@qq.com","author":"lijunxi","message":"jenkins+gitlab"},{"hash":"a079ea7e97002eff270e73de6138f3c933e4ce0f","time":1764428419000,"email":"2770063826@qq.com","author":"lijunxi","message":"update gulimall、linux"},{"hash":"a004474c8ef0c644f4795d36c2bf21867959454d","time":1761318760000,"email":"2770063826@qq.com","author":"lijunxi","message":"add mybatis-cache"},{"hash":"db3c37f1fcda437aa337bbcb1223dcfc881791f8","time":1757515294000,"email":"2770063826@qq.com","author":"lijunxi","message":"update note"},{"hash":"5cdf854fdecfe3948cf24fe4a4b2297f10de33fe","time":1755609751000,"email":"2770063826@qq.com","author":"lijunxi","message":"add netty"},{"hash":"79eec738f6a7524e515e4fe9f201ca1fff237c08","time":1753533208000,"email":"2770063826@qq.com","author":"lijunxi","message":"add gulimall etc."},{"hash":"fda24bba0aaf0c659a0fe19f8a73f0ae17a879c8","time":1751641124000,"email":"2770063826@qq.com","author":"lijunxi","message":"整合笔记"}]},"filePathRelative":"linux/Linux环境配置常用命令.md"}');export{c as comp,d as data};
